/**
 * Privacy policy and terms of service, carried over word for word from the
 * previous octopos.uz (landingpage repo, src/i18n/*.ts) so the indexed
 * /privacy and /terms pages keep their content. Turkish had no version there:
 * it shows the English text until a translation exists.
 */
import type { Lang } from "./i18n";

export const LEGAL_SECTIONS = { privacy: 12, terms: 13 } as const;

export const LEGAL: Record<string, Partial<Record<Lang, string>>> = {
  "legal.privacy.title": {"uz": "Maxfiylik siyosati", "en": "Privacy Policy", "ru": "Политика конфиденциальности", "ko": "개인정보 처리방침", "tr": "Gizlilik Politikası"},
  "legal.privacy.heading": {"en": "Privacy Policy", "uz": "Maxfiylik siyosati", "ru": "Политика конфиденциальности", "ko": "개인정보 처리방침", "tr": "Privacy Policy"},
  "legal.privacy.effective": {"en": "Last updated: 10 July 2026", "uz": "Oxirgi yangilanish: 2026-yil 10-iyul", "ru": "Последнее обновление: 10 июля 2026 г.", "ko": "최종 업데이트: 2026년 7월 10일", "tr": "Last updated: 10 July 2026"},
  "legal.privacy.intro": {"en": "This Privacy Policy explains how Octopos handles your personal information when you use our websites and apps — Guest, POS, Kitchen, Order Display and Dash — and related services (together, the “Services”). We process personal data in accordance with the legislation of the Republic of Uzbekistan, including the Law “On Personal Data”.", "uz": "Ushbu Maxfiylik siyosati Octopos veb-saytlari va ilovalari — Guest, POS, Kitchen, Order Display va Dash — hamda tegishli xizmatlardan (birgalikda — «Xizmatlar») foydalanganingizda shaxsiy maʼlumotlaringiz bilan qanday ish tutishimizni tushuntiradi. Biz shaxsiy maʼlumotlarni Oʻzbekiston Respublikasi qonunchiligiga, jumladan «Shaxsga doir maʼlumotlar toʻgʻrisida»gi Qonunga muvofiq qayta ishlaymiz.", "ru": "Настоящая Политика конфиденциальности объясняет, как Octopos обращается с вашей персональной информацией при использовании наших сайтов и приложений — Guest, POS, Kitchen, Order Display и Dash — и связанных с ними сервисов (совместно — «Сервисы»). Мы обрабатываем персональные данные в соответствии с законодательством Республики Узбекистан, включая Закон «О персональных данных».", "ko": "본 개인정보처리방침은 Octopos 웹사이트 및 앱 — Guest, POS, Kitchen, Order Display, Dash — 과 관련 서비스(총칭 “서비스”)를 사용할 때 귀하의 개인정보를 어떻게 처리하는지 설명합니다. 당사는 「개인정보 보호법」을 포함한 우즈베키스탄 공화국 법률에 따라 개인정보를 처리합니다.", "tr": "This Privacy Policy explains how Octopos handles your personal information when you use our websites and apps — Guest, POS, Kitchen, Order Display and Dash — and related services (together, the “Services”). We process personal data in accordance with the legislation of the Republic of Uzbekistan, including the Law “On Personal Data”."},
  "legal.privacy.s1t": {"en": "1. What this Policy covers", "uz": "1. Siyosat nimani qamrab oladi", "ru": "1. На что распространяется Политика", "ko": "1. 본 방침의 적용 범위", "tr": "1. What this Policy covers"},
  "legal.privacy.s1b": {"en": "This Policy covers information that may identify you (“personal information”) collected when you visit octopos.uz or use any Octopos product — Guest QR ordering, POS, Kitchen Display, Order Display and the Dash back office. Some data reaches us through our partners — the restaurants and cafés that use Octopos to serve you — under agreements that require them to share it lawfully.", "uz": "Siyosat octopos.uz saytiga tashrif buyurganingizda yoki istalgan Octopos mahsulotidan — Guest QR-buyurtma, POS, Kitchen oshxona ekrani, Order Display buyurtmalar tablosi va Dash bek-ofisidan — foydalanganingizda toʻplanadigan, sizni aniqlashi mumkin boʻlgan maʼlumotlarni («shaxsiy maʼlumot») qamrab oladi. Ayrim maʼlumotlar bizga hamkorlar — sizga xizmat koʻrsatish uchun Octopos’dan foydalanadigan restoran va kafelar — orqali, ularni qonuniy uzatishni talab qiluvchi shartnomalar asosida yetib keladi.", "ru": "Политика охватывает информацию, которая может вас идентифицировать («персональная информация»), собираемую при посещении octopos.uz или использовании любого продукта Octopos — QR-заказа Guest, POS, кухонного экрана Kitchen, табло заказов Order Display и бэк-офиса Dash. Часть данных поступает к нам через партнёров — рестораны и кафе, которые используют Octopos для вашего обслуживания, — на основании договоров, обязывающих передавать данные законно.", "ko": "본 방침은 octopos.uz 방문 또는 Octopos 제품 — Guest QR 주문, POS, Kitchen 주방 디스플레이, Order Display 주문 표시, Dash 백오피스 — 이용 시 수집되어 귀하를 식별할 수 있는 정보(“개인정보”)를 다룹니다. 일부 데이터는 Octopos로 귀하를 응대하는 파트너(레스토랑·카페)를 통해, 적법한 공유를 요구하는 계약에 따라 당사에 전달됩니다.", "tr": "This Policy covers information that may identify you (“personal information”) collected when you visit octopos.uz or use any Octopos product — Guest QR ordering, POS, Kitchen Display, Order Display and the Dash back office. Some data reaches us through our partners — the restaurants and cafés that use Octopos to serve you — under agreements that require them to share it lawfully."},
  "legal.privacy.s2t": {"en": "2. Who is responsible for your data", "uz": "2. Maʼlumotlaringiz uchun kim javobgar", "ru": "2. Кто отвечает за ваши данные", "ko": "2. 데이터 책임 주체", "tr": "2. Who is responsible for your data"},
  "legal.privacy.s2b": {"en": "Octopos is operated by Octopos Soft LLC, a company incorporated under the laws of the Republic of Uzbekistan, registered at 12 Navoiy Street, Namangan 160100, Republic of Uzbekistan (“Octopos”, “we”). We decide why and how your personal information is processed. For any privacy question, write to support@octopos.uz.", "uz": "Octopos Octopos Soft MChJ tomonidan boshqariladi — Oʻzbekiston Respublikasi qonunchiligiga muvofiq Navoiy koʻchasi, 12, Namangan shahri, 160100, Oʻzbekiston Respublikasi manzilida roʻyxatdan oʻtgan kompaniya («Octopos», «biz»). Shaxsiy maʼlumotlaringiz nima uchun va qanday qayta ishlanishini biz belgilaymiz. Maxfiylik boʻyicha savollar uchun support@octopos.uz manziliga yozing.", "ru": "Octopos управляется компанией Octopos Soft LLC, зарегистрированной по законодательству Республики Узбекистан по адресу ул. Навоий, 12, г. Наманган, 160100, Республика Узбекистан («Octopos», «мы»). Мы определяем, зачем и как обрабатывается ваша персональная информация. По вопросам конфиденциальности пишите на support@octopos.uz.", "ko": "Octopos는 우즈베키스탄 공화국 법률에 따라 우즈베키스탄 나망간 Navoiy Street 12, 160100에 등록된 회사 Octopos Soft LLC(“Octopos”, “당사”)이 운영합니다. 당사가 개인정보 처리의 목적과 방법을 결정합니다. 개인정보 관련 문의는 support@octopos.uz 로 보내주세요.", "tr": "Octopos is operated by Octopos Soft LLC, a company incorporated under the laws of the Republic of Uzbekistan, registered at 12 Navoiy Street, Namangan 160100, Republic of Uzbekistan (“Octopos”, “we”). We decide why and how your personal information is processed. For any privacy question, write to support@octopos.uz."},
  "legal.privacy.s3t": {"en": "3. Purpose of this Policy", "uz": "3. Ushbu Siyosatning maqsadi", "ru": "3. Цель настоящей Политики", "ko": "3. 본 방침의 목적", "tr": "3. Purpose of this Policy"},
  "legal.privacy.s3b": {"en": "Your privacy matters to us. This Policy transparently explains what personal information we collect, why and how we use it, how we protect it, the choices you have and your rights under the law of Uzbekistan.", "uz": "Maxfiyligingiz biz uchun muhim. Ushbu Siyosat qanday shaxsiy maʼlumot toʻplashimizni, uni nima uchun va qanday ishlatishimizni, qanday himoya qilishimizni, sizdagi tanlov imkoniyatlari va Oʻzbekiston qonunchiligidagi huquqlaringizni shaffof tushuntiradi.", "ru": "Ваша конфиденциальность важна для нас. Политика прозрачно объясняет, какую персональную информацию мы собираем, зачем и как её используем, как защищаем, какие у вас есть возможности выбора и права согласно законодательству Узбекистана.", "ko": "귀하의 프라이버시는 당사에 중요합니다. 본 방침은 어떤 개인정보를 수집하고, 왜·어떻게 사용하며, 어떻게 보호하는지, 그리고 우즈베키스탄 법에 따른 귀하의 선택권과 권리를 투명하게 설명합니다.", "tr": "Your privacy matters to us. This Policy transparently explains what personal information we collect, why and how we use it, how we protect it, the choices you have and your rights under the law of Uzbekistan."},
  "legal.privacy.s4t": {"en": "4. Information we collect", "uz": "4. Qanday maʼlumot toʻplaymiz", "ru": "4. Какие данные мы собираем", "ko": "4. 수집하는 정보", "tr": "4. Information we collect"},
  "legal.privacy.s4b": {"en": "Depending on how you use the Services, we may collect: account details you provide (name, mobile number, restaurant or business name); technical data (IP address, device and browser information, cookies and similar identifiers); usage data (orders placed, menu items viewed, actions in the apps, and access dates and times); approximate location where relevant; and information partners share with us under our agreements. Guests can browse and order via a QR code without creating an account — in that case we process only the data needed to complete the order. We do not intentionally collect special categories of data and do not carry out profiling that produces legal effects for you.", "uz": "Xizmatlardan qanday foydalanishingizga qarab biz quyidagilarni toʻplashimiz mumkin: siz taqdim etadigan hisob maʼlumotlari (ism, telefon raqami, restoran yoki biznes nomi); texnik maʼlumotlar (IP-manzil, qurilma va brauzer haqidagi maʼlumot, cookie va shunga oʻxshash identifikatorlar); foydalanish maʼlumotlari (berilgan buyurtmalar, koʻrilgan menyu taomlari, ilovalardagi harakatlar, kirish sanasi va vaqti); zarur boʻlganda taxminiy joylashuv; hamda hamkorlar shartnoma asosida uzatadigan maʼlumotlar. Mehmonlar hisob yaratmasdan QR-kod orqali menyuni koʻrishi va buyurtma berishi mumkin — bunda biz faqat buyurtmani bajarish uchun zarur maʼlumotni qayta ishlaymiz. Biz maxsus toifadagi maʼlumotlarni ataylab toʻplamaymiz va siz uchun huquqiy oqibat keltiruvchi profillashtirishni amalga oshirmaymiz.", "ru": "В зависимости от того, как вы используете Сервисы, мы можем собирать: данные учётной записи, которые вы предоставляете (имя, номер телефона, название ресторана или бизнеса); технические данные (IP-адрес, сведения об устройстве и браузере, файлы cookie и подобные идентификаторы); данные об использовании (оформленные заказы, просмотренные позиции меню, действия в приложениях, дата и время доступа); приблизительное местоположение, если это необходимо; а также сведения, которые партнёры передают нам по договорам. Гости могут просматривать меню и заказывать по QR-коду без создания учётной записи — в этом случае мы обрабатываем только данные, необходимые для выполнения заказа. Мы не собираем намеренно особые категории данных и не проводим профилирование, влекущее для вас юридические последствия.", "ko": "서비스 이용 방식에 따라 당사는 다음을 수집할 수 있습니다: 귀하가 제공하는 계정 정보(이름, 휴대폰 번호, 레스토랑·사업체명); 기술 데이터(IP 주소, 기기·브라우저 정보, 쿠키 및 유사 식별자); 이용 데이터(주문 내역, 조회한 메뉴, 앱 내 활동, 접속 일시); 필요한 경우 대략적 위치; 계약에 따라 파트너가 공유하는 정보. 게스트는 계정 없이 QR 코드로 메뉴를 보고 주문할 수 있으며, 이 경우 주문 완료에 필요한 데이터만 처리합니다. 당사는 민감정보를 의도적으로 수집하지 않으며 법적 효력을 발생시키는 프로파일링을 수행하지 않습니다.", "tr": "Depending on how you use the Services, we may collect: account details you provide (name, mobile number, restaurant or business name); technical data (IP address, device and browser information, cookies and similar identifiers); usage data (orders placed, menu items viewed, actions in the apps, and access dates and times); approximate location where relevant; and information partners share with us under our agreements. Guests can browse and order via a QR code without creating an account — in that case we process only the data needed to complete the order. We do not intentionally collect special categories of data and do not carry out profiling that produces legal effects for you."},
  "legal.privacy.s5t": {"en": "5. Why we process your data", "uz": "5. Maʼlumotni nima uchun qayta ishlaymiz", "ru": "5. Зачем мы обрабатываем данные", "ko": "5. 처리 목적과 근거", "tr": "5. Why we process your data"},
  "legal.privacy.s5b": {"en": "We process personal information only where we have a lawful basis under the legislation of the Republic of Uzbekistan: to perform our agreement with you and deliver the Services; to comply with legal obligations; for our legitimate interests (keeping the Services secure, available and improving them); or with your consent where it is required. We use your data to operate the Services; create and manage accounts; take, route and display orders across Guest, POS, Kitchen and Order Display; produce analytics and reports in Dash; provide support; keep the Services safe; and build new features. Providing personal information is voluntary, but without it some Services may be unavailable.", "uz": "Biz shaxsiy maʼlumotni faqat Oʻzbekiston Respublikasi qonunchiligidagi qonuniy asos boʻlganda qayta ishlaymiz: siz bilan tuzilgan shartnomani bajarish va Xizmatlarni taqdim etish uchun; qonun talablariga rioya qilish uchun; qonuniy manfaatlarimiz uchun (Xizmatlar xavfsizligi, mavjudligi va yaxshilanishi); yoki talab etilganda roziligingiz bilan. Maʼlumotdan Xizmatlarni ishlatish; hisoblarni yaratish va boshqarish; Guest, POS, Kitchen va Order Display boʻylab buyurtmalarni qabul qilish, yoʻnaltirish va koʻrsatish; Dash’da tahlil va hisobotlar tayyorlash; qoʻllab-quvvatlash; xavfsizlikni taʼminlash; va yangi imkoniyatlar yaratish uchun foydalanamiz. Shaxsiy maʼlumot berish ixtiyoriy, lekin usiz ayrim Xizmatlar mavjud boʻlmasligi mumkin.", "ru": "Мы обрабатываем персональную информацию только при наличии законного основания по законодательству Республики Узбекистан: для исполнения договора с вами и предоставления Сервисов; для выполнения требований закона; в наших законных интересах (обеспечение безопасности, доступности и улучшения Сервисов); либо с вашего согласия, когда оно требуется. Мы используем данные, чтобы обеспечивать работу Сервисов; создавать учётные записи и управлять ими; принимать, маршрутизировать и отображать заказы в Guest, POS, Kitchen и Order Display; формировать аналитику и отчёты в Dash; оказывать поддержку; обеспечивать безопасность; и разрабатывать новые функции. Предоставление персональной информации добровольно, но без неё часть Сервисов может быть недоступна.", "ko": "당사는 우즈베키스탄 공화국 법률상 적법 근거가 있는 경우에만 개인정보를 처리합니다: 귀하와의 계약 이행 및 서비스 제공; 법적 의무 준수; 정당한 이익(서비스의 보안·가용성 유지 및 개선); 또는 필요한 경우 귀하의 동의. 당사는 서비스 운영; 계정 생성·관리; Guest·POS·Kitchen·Order Display 전반의 주문 접수·라우팅·표시; Dash의 분석·리포트 생성; 지원 제공; 보안 유지; 신규 기능 개발을 위해 데이터를 사용합니다. 개인정보 제공은 자발적이나, 제공하지 않으면 일부 서비스를 이용할 수 없습니다.", "tr": "We process personal information only where we have a lawful basis under the legislation of the Republic of Uzbekistan: to perform our agreement with you and deliver the Services; to comply with legal obligations; for our legitimate interests (keeping the Services secure, available and improving them); or with your consent where it is required. We use your data to operate the Services; create and manage accounts; take, route and display orders across Guest, POS, Kitchen and Order Display; produce analytics and reports in Dash; provide support; keep the Services safe; and build new features. Providing personal information is voluntary, but without it some Services may be unavailable."},
  "legal.privacy.s6t": {"en": "6. How we share your data", "uz": "6. Maʼlumotni kimga beramiz", "ru": "6. Кому мы передаём данные", "ko": "6. 정보 공유", "tr": "6. How we share your data"},
  "legal.privacy.s6b": {"en": "We share personal information only as needed to run the Services: with the partner restaurant or café you interact with; with service providers acting on our behalf (such as hosting, SMS and notifications, payment and delivery integrations, anti-bot/captcha and analytics), who may process only the data required for their task; and with state bodies or courts where the law requires. We may also transfer data as part of a corporate reorganisation, or to third parties where you have given your consent. We do not sell your personal information.", "uz": "Biz shaxsiy maʼlumotni faqat Xizmatlar ishlashi uchun zarur hajmda ulashamiz: siz muloqot qilayotgan hamkor restoran yoki kafe bilan; bizning topshirigʻimiz asosida ishlaydigan xizmat provayderlari bilan (masalan, hosting, SMS va bildirishnomalar, toʻlov va yetkazib berish integratsiyalari, botlarga qarshi/kapcha va tahlil), ular faqat oʻz vazifasi uchun zarur maʼlumotni qayta ishlaydi; hamda qonun talab qilganda davlat organlari yoki sudlar bilan. Shuningdek, kompaniyani qayta tashkil etishda yoki roziligingiz boʻlganda uchinchi shaxslarga maʼlumot uzatishimiz mumkin. Biz shaxsiy maʼlumotingizni sotmaymiz.", "ru": "Мы передаём персональную информацию только в объёме, необходимом для работы Сервисов: партнёру — ресторану или кафе, с которым вы взаимодействуете; поставщикам услуг, действующим по нашему поручению (хостинг, SMS и уведомления, платёжные и доставочные интеграции, защита от ботов/капча, аналитика), которые обрабатывают только необходимые для их задачи данные; а также государственным органам или судам, когда этого требует закон. Мы также можем передавать данные в рамках реорганизации компании или третьим лицам при наличии вашего согласия. Мы не продаём вашу персональную информацию.", "ko": "당사는 서비스 운영에 필요한 범위에서만 개인정보를 공유합니다: 귀하가 상호작용하는 파트너 레스토랑·카페; 당사를 대신하는 서비스 제공자(호스팅, SMS·알림, 결제·배달 연동, 봇 방지/캡차, 분석 등)로서 각자의 업무에 필요한 데이터만 처리; 법이 요구하는 경우 국가기관 또는 법원. 또한 기업 구조조정 과정에서, 또는 귀하의 동의가 있는 경우 제3자에게 이전할 수 있습니다. 당사는 개인정보를 판매하지 않습니다.", "tr": "We share personal information only as needed to run the Services: with the partner restaurant or café you interact with; with service providers acting on our behalf (such as hosting, SMS and notifications, payment and delivery integrations, anti-bot/captcha and analytics), who may process only the data required for their task; and with state bodies or courts where the law requires. We may also transfer data as part of a corporate reorganisation, or to third parties where you have given your consent. We do not sell your personal information."},
  "legal.privacy.s7t": {"en": "7. Where we store your data", "uz": "7. Maʼlumot qayerda saqlanadi", "ru": "7. Где хранятся ваши данные", "ko": "7. 정보 보관 위치", "tr": "7. Where we store your data"},
  "legal.privacy.s7b": {"en": "In accordance with the personal-data legislation of the Republic of Uzbekistan, personal information of users in Uzbekistan is recorded and stored using databases located in the territory of the Republic of Uzbekistan.", "uz": "Oʻzbekiston Respublikasining shaxsga doir maʼlumotlar toʻgʻrisidagi qonunchiligiga muvofiq, Oʻzbekistondagi foydalanuvchilarning shaxsiy maʼlumotlari Oʻzbekiston Respublikasi hududida joylashgan maʼlumotlar bazalaridan foydalangan holda yoziladi va saqlanadi.", "ru": "В соответствии с законодательством Республики Узбекистан о персональных данных персональная информация пользователей в Узбекистане записывается и хранится с использованием баз данных, расположенных на территории Республики Узбекистан.", "ko": "우즈베키스탄 공화국 개인정보 법률에 따라, 우즈베키스탄 이용자의 개인정보는 우즈베키스탄 공화국 영토 내에 위치한 데이터베이스를 사용하여 기록·보관됩니다.", "tr": "In accordance with the personal-data legislation of the Republic of Uzbekistan, personal information of users in Uzbekistan is recorded and stored using databases located in the territory of the Republic of Uzbekistan."},
  "legal.privacy.s8t": {"en": "8. How long we keep your data", "uz": "8. Maʼlumotni qancha saqlaymiz", "ru": "8. Сколько мы храним данные", "ko": "8. 보관 기간", "tr": "8. How long we keep your data"},
  "legal.privacy.s8b": {"en": "We keep personal information only for as long as necessary for the purposes described above or as required by law. Data linked to your account is kept while the account is active; you can delete content or your account at any time from the app. After closure we delete or anonymise the data unless a longer period is legally required.", "uz": "Biz shaxsiy maʼlumotni faqat yuqoridagi maqsadlar uchun zarur boʻlgan yoki qonun talab qilgan muddatgacha saqlaymiz. Hisobingizga bogʻliq maʼlumotlar hisob faol boʻlgunicha saqlanadi; kontent yoki hisobni istalgan vaqtda ilovadan oʻchirishingiz mumkin. Hisob yopilgach, qonun uzoqroq muddatni talab qilmasa, maʼlumotlarni oʻchiramiz yoki anonimlashtiramiz.", "ru": "Мы храним персональную информацию только столько, сколько необходимо для указанных целей или требуется законом. Данные, связанные с вашей учётной записью, хранятся, пока она активна; вы можете в любой момент удалить контент или саму учётную запись в приложении. После закрытия мы удаляем или обезличиваем данные, если более длительный срок не требуется по закону.", "ko": "당사는 위 목적에 필요한 기간 또는 법이 요구하는 기간 동안에만 개인정보를 보관합니다. 계정과 연결된 데이터는 계정이 활성화된 동안 보관되며, 앱에서 언제든 콘텐츠나 계정을 삭제할 수 있습니다. 계정 종료 후에는 법이 더 긴 기간을 요구하지 않는 한 데이터를 삭제하거나 익명화합니다.", "tr": "We keep personal information only for as long as necessary for the purposes described above or as required by law. Data linked to your account is kept while the account is active; you can delete content or your account at any time from the app. After closure we delete or anonymise the data unless a longer period is legally required."},
  "legal.privacy.s9t": {"en": "9. How we protect your data", "uz": "9. Maʼlumotni qanday himoya qilamiz", "ru": "9. Как мы защищаем данные", "ko": "9. 정보 보호", "tr": "9. How we protect your data"},
  "legal.privacy.s9b": {"en": "Most processing is automated, without staff access. Where access is necessary, only authorised employees who are bound by confidentiality may access your data, and only for defined tasks. We apply organisational and technical safeguards appropriate to the risk to protect personal information from unauthorised access, loss, alteration or disclosure.", "uz": "Qayta ishlashning aksariyati xodimlar aralashuvisiz avtomatik amalga oshiriladi. Kirish zarur boʻlganda, maʼlumotlaringizga faqat maxfiylik majburiyatiga bogʻlangan vakolatli xodimlar, faqat belgilangan vazifalar uchun kira oladi. Biz shaxsiy maʼlumotni ruxsatsiz kirish, yoʻqotish, oʻzgartirish yoki oshkor qilishdan himoya qilish uchun xavfga mos tashkiliy va texnik choralarni qoʻllaymiz.", "ru": "Большая часть обработки выполняется автоматически, без доступа сотрудников. Когда доступ необходим, к вашим данным допускаются только уполномоченные сотрудники, связанные обязательством о конфиденциальности, и только для определённых задач. Мы применяем организационные и технические меры, соразмерные рискам, для защиты персональной информации от несанкционированного доступа, утраты, изменения или раскрытия.", "ko": "대부분의 처리는 직원 접근 없이 자동으로 이루어집니다. 접근이 필요한 경우, 기밀 유지 의무가 있는 승인된 직원만이 지정된 업무를 위해 접근할 수 있습니다. 당사는 무단 접근·손실·변경·유출로부터 개인정보를 보호하기 위해 위험에 상응하는 관리적·기술적 보호조치를 적용합니다.", "tr": "Most processing is automated, without staff access. Where access is necessary, only authorised employees who are bound by confidentiality may access your data, and only for defined tasks. We apply organisational and technical safeguards appropriate to the risk to protect personal information from unauthorised access, loss, alteration or disclosure."},
  "legal.privacy.s10t": {"en": "10. Your rights", "uz": "10. Sizning huquqlaringiz", "ru": "10. Ваши права", "ko": "10. 귀하의 권리", "tr": "10. Your rights"},
  "legal.privacy.s10b": {"en": "Subject to applicable law, you may access the personal information we hold about you, correct it, request its deletion, withdraw your consent, or ask us to restrict its processing. You can manage much of your data directly in your account. To exercise your rights, or if you have a concern, contact support@octopos.uz. If you are not satisfied with our response, you may lodge a complaint with the competent data-protection authority of the Republic of Uzbekistan.", "uz": "Amaldagi qonunchilikka muvofiq siz oʻzingiz haqingizdagi shaxsiy maʼlumotdan foydalanishingiz, uni toʻgʻrilashingiz, oʻchirishni talab qilishingiz, rozilikni qaytarib olishingiz yoki qayta ishlashni cheklashni soʻrashingiz mumkin. Maʼlumotning katta qismini toʻgʻridan-toʻgʻri hisobingizda boshqarasiz. Huquqlaringizdan foydalanish yoki muammo boʻyicha support@octopos.uz manziliga murojaat qiling. Javobimizdan qoniqmasangiz, Oʻzbekiston Respublikasining shaxsiy maʼlumotlarni himoya qilish boʻyicha vakolatli organiga shikoyat qilishingiz mumkin.", "ru": "В соответствии с применимым правом вы можете получить доступ к своей персональной информации, исправить её, потребовать удаления, отозвать согласие или ограничить обработку. Большую часть данных можно изменить прямо в учётной записи. Чтобы воспользоваться правами или сообщить о проблеме, напишите на support@octopos.uz. Если наш ответ вас не устроит, вы вправе обратиться с жалобой в уполномоченный орган Республики Узбекистан по защите персональных данных.", "ko": "관련 법에 따라 귀하는 당사가 보유한 개인정보에 접근, 정정, 삭제 요청, 동의 철회, 처리 제한을 요청할 수 있습니다. 많은 데이터는 계정에서 직접 관리할 수 있습니다. 권리 행사 또는 문의는 support@octopos.uz 로 연락해 주세요. 당사의 답변에 만족하지 못하는 경우, 우즈베키스탄 공화국의 관할 개인정보 보호기관에 이의를 제기할 수 있습니다.", "tr": "Subject to applicable law, you may access the personal information we hold about you, correct it, request its deletion, withdraw your consent, or ask us to restrict its processing. You can manage much of your data directly in your account. To exercise your rights, or if you have a concern, contact support@octopos.uz. If you are not satisfied with our response, you may lodge a complaint with the competent data-protection authority of the Republic of Uzbekistan."},
  "legal.privacy.s11t": {"en": "11. Cookies and similar technologies", "uz": "11. Cookie va shunga oʻxshash texnologiyalar", "ru": "11. Файлы cookie и подобные технологии", "ko": "11. 쿠키 및 유사 기술", "tr": "11. Cookies and similar technologies"},
  "legal.privacy.s11b": {"en": "We use cookies and similar technologies (such as pixels) to run the Sites, remember your preferences (like language and theme), measure usage and improve the Services, and — where permitted — to show relevant advertising. You can accept or decline non-essential cookies and manage them in your browser settings; disabling some cookies may limit certain features.", "uz": "Biz Saytlarni ishlatish, sozlamalaringizni (til va mavzu) eslab qolish, foydalanishni oʻlchash va Xizmatlarni yaxshilash, hamda ruxsat etilgan joyda tegishli reklamani koʻrsatish uchun cookie va shunga oʻxshash texnologiyalardan (masalan, piksellar) foydalanamiz. Majburiy boʻlmagan cookie’larni qabul qilishingiz yoki rad etishingiz va ularni brauzer sozlamalarida boshqarishingiz mumkin; ayrim cookie’larni oʻchirish baʼzi funksiyalarni cheklashi mumkin.", "ru": "Мы используем файлы cookie и подобные технологии (например, пиксели), чтобы обеспечивать работу Сайтов, запоминать ваши настройки (язык и тему), измерять использование и улучшать Сервисы, а также — где это разрешено — показывать релевантную рекламу. Вы можете принять или отклонить необязательные cookie и управлять ими в настройках браузера; отключение части cookie может ограничить некоторые функции.", "ko": "당사는 사이트 운영, 설정(언어·테마) 기억, 이용 측정 및 서비스 개선, 그리고 허용되는 경우 관련 광고 표시를 위해 쿠키 및 유사 기술(예: 픽셀)을 사용합니다. 필수가 아닌 쿠키는 수락 또는 거부할 수 있고 브라우저 설정에서 관리할 수 있으며, 일부 쿠키를 비활성화하면 특정 기능이 제한될 수 있습니다.", "tr": "We use cookies and similar technologies (such as pixels) to run the Sites, remember your preferences (like language and theme), measure usage and improve the Services, and — where permitted — to show relevant advertising. You can accept or decline non-essential cookies and manage them in your browser settings; disabling some cookies may limit certain features."},
  "legal.privacy.s12t": {"en": "12. Changes and contact", "uz": "12. Oʻzgarishlar va aloqa", "ru": "12. Изменения и контакты", "ko": "12. 변경 및 문의", "tr": "12. Changes and contact"},
  "legal.privacy.s12b": {"en": "We may update this Policy from time to time — for example to reflect changes in the law or in the Services. We will not reduce your rights without appropriate notice, which we may give on the Sites or by email. Questions, requests and suggestions are welcome at support@octopos.uz.", "uz": "Biz ushbu Siyosatni vaqti-vaqti bilan yangilashimiz mumkin — masalan, qonun yoki Xizmatlardagi oʻzgarishlarni aks ettirish uchun. Tegishli xabar bermasdan huquqlaringizni qisqartirmaymiz; bunday xabarni Saytlarda yoki elektron pochta orqali berishimiz mumkin. Savollar, soʻrovlar va takliflarni support@octopos.uz manziliga yuborishingiz mumkin.", "ru": "Мы можем периодически обновлять эту Политику — например, при изменении законодательства или Сервисов. Мы не будем сокращать ваши права без надлежащего уведомления, которое можем разместить на Сайтах или направить по электронной почте. Вопросы, запросы и предложения приветствуются на support@octopos.uz.", "ko": "당사는 법률 또는 서비스 변경 등을 반영하기 위해 본 방침을 수시로 업데이트할 수 있습니다. 적절한 통지 없이 귀하의 권리를 축소하지 않으며, 통지는 사이트 또는 이메일로 제공될 수 있습니다. 질문·요청·제안은 support@octopos.uz 로 환영합니다.", "tr": "We may update this Policy from time to time — for example to reflect changes in the law or in the Services. We will not reduce your rights without appropriate notice, which we may give on the Sites or by email. Questions, requests and suggestions are welcome at support@octopos.uz."},
  "legal.terms.title": {"uz": "Foydalanish shartlari", "en": "Terms of Service", "ru": "Условия использования", "ko": "서비스 이용약관", "tr": "Hizmet Şartları"},
  "legal.terms.heading": {"en": "Terms of Service", "uz": "Xizmat ko‘rsatish shartlari", "ru": "Условия обслуживания", "ko": "이용 약관", "tr": "Terms of Service"},
  "legal.terms.effective": {"en": "Last updated: 10 July 2026", "uz": "Oxirgi yangilanish: 2026-yil 10-iyul", "ru": "Последнее обновление: 10 июля 2026 г.", "ko": "최종 업데이트: 2026년 7월 10일", "tr": "Last updated: 10 July 2026"},
  "legal.terms.intro": {"en": "These Terms of Use (the “Terms”) govern your access to and use of the Octopos websites and apps — Guest, POS, Kitchen, Order Display and Dash — and related services (together, the “Services”). By using the Services you agree to these Terms. If you do not agree, please do not use the Services.", "uz": "Ushbu Foydalanish shartlari («Shartlar») Octopos veb-saytlari va ilovalari — Guest, POS, Kitchen, Order Display va Dash — hamda tegishli xizmatlardan (birgalikda — «Xizmatlar») foydalanishingizni tartibga soladi. Xizmatlardan foydalanish orqali siz ushbu Shartlarni qabul qilasiz. Rozi boʻlmasangiz, Xizmatlardan foydalanmang.", "ru": "Настоящие Условия использования («Условия») регулируют ваш доступ к сайтам и приложениям Octopos — Guest, POS, Kitchen, Order Display и Dash — и связанным сервисам (совместно — «Сервисы»), а также их использование. Используя Сервисы, вы принимаете настоящие Условия. Если вы не согласны, не используйте Сервисы.", "ko": "본 이용약관(“약관”)은 Octopos 웹사이트 및 앱 — Guest, POS, Kitchen, Order Display, Dash — 과 관련 서비스(총칭 “서비스”)에 대한 접근 및 이용을 규율합니다. 서비스를 이용함으로써 귀하는 본 약관에 동의합니다. 동의하지 않으면 서비스를 이용하지 마십시오.", "tr": "These Terms of Use (the “Terms”) govern your access to and use of the Octopos websites and apps — Guest, POS, Kitchen, Order Display and Dash — and related services (together, the “Services”). By using the Services you agree to these Terms. If you do not agree, please do not use the Services."},
  "legal.terms.s1t": {"en": "1. Acceptance and scope", "uz": "1. Qabul qilish va qoʻllanish doirasi", "ru": "1. Принятие и сфера действия", "ko": "1. 동의 및 적용 범위", "tr": "1. Acceptance and scope"},
  "legal.terms.s1b": {"en": "These Terms form a binding agreement between you and Octopos. They apply whenever you access octopos.uz or use any Octopos product. Some Services may have additional terms that apply together with these Terms; if there is a conflict, the additional terms prevail for that Service.", "uz": "Ushbu Shartlar siz bilan Octopos oʻrtasidagi majburiy kelishuvdir. Ular octopos.uz saytiga kirganingizda va istalgan Octopos mahsulotidan foydalanganingizda qoʻllanadi. Ayrim Xizmatlar uchun qoʻshimcha shartlar boʻlishi mumkin; ular ushbu Shartlar bilan birga amal qiladi, ziddiyat boʻlsa oʻsha Xizmat uchun qoʻshimcha shartlar ustuvor boʻladi.", "ru": "Настоящие Условия являются обязательным соглашением между вами и Octopos. Они применяются при доступе к octopos.uz и использовании любого продукта Octopos. Для отдельных Сервисов могут действовать дополнительные условия, применяемые совместно с настоящими; при противоречии для такого Сервиса приоритет имеют дополнительные условия.", "ko": "본 약관은 귀하와 Octopos 간의 구속력 있는 계약입니다. octopos.uz 접속 또는 Octopos 제품 이용 시 적용됩니다. 일부 서비스에는 본 약관과 함께 적용되는 추가 약관이 있을 수 있으며, 상충하는 경우 해당 서비스에 대해 추가 약관이 우선합니다.", "tr": "These Terms form a binding agreement between you and Octopos. They apply whenever you access octopos.uz or use any Octopos product. Some Services may have additional terms that apply together with these Terms; if there is a conflict, the additional terms prevail for that Service."},
  "legal.terms.s2t": {"en": "2. Who we are", "uz": "2. Biz kimmiz", "ru": "2. Кто мы", "ko": "2. 회사 정보", "tr": "2. Who we are"},
  "legal.terms.s2b": {"en": "The Services are provided by Octopos Soft LLC, a company incorporated under the laws of the Republic of Uzbekistan, registered at 12 Navoiy Street, Namangan 160100, Uzbekistan (“Octopos”, “we”). You can reach us at support@octopos.uz.", "uz": "Xizmatlar Octopos Soft MChJ tomonidan taqdim etiladi — Oʻzbekiston Respublikasi qonunchiligiga muvofiq Navoiy koʻchasi, 12, Namangan shahri, 160100, Oʻzbekiston manzilida roʻyxatdan oʻtgan («Octopos», «biz»). Biz bilan support@octopos.uz orqali bogʻlanishingiz mumkin.", "ru": "Сервисы предоставляет Octopos Soft LLC, зарегистрированная по законодательству Республики Узбекистан по адресу: ул. Навоий, 12, г. Наманган, 160100, Узбекистан («Octopos», «мы»). Связаться с нами можно по адресу support@octopos.uz.", "ko": "서비스는 우즈베키스탄 공화국 법률에 따라 우즈베키스탄 나망간 Navoiy Street 12, 160100에 등록된 Octopos Soft LLC(“Octopos”, “당사”)가 제공합니다. 문의는 support@octopos.uz 로 연락해 주세요.", "tr": "The Services are provided by Octopos Soft LLC, a company incorporated under the laws of the Republic of Uzbekistan, registered at 12 Navoiy Street, Namangan 160100, Uzbekistan (“Octopos”, “we”). You can reach us at support@octopos.uz."},
  "legal.terms.s3t": {"en": "3. The Octopos Services", "uz": "3. Octopos Xizmatlari", "ru": "3. Сервисы Octopos", "ko": "3. Octopos 서비스", "tr": "3. The Octopos Services"},
  "legal.terms.s3b": {"en": "Octopos is an all-in-one restaurant platform: Guest (QR menu and self-ordering), POS (point of sale and floor management), Kitchen (kitchen display), Order Display (pickup status screen) and Dash (back-office analytics, inventory, finance and staff). We may add, change or discontinue features to improve the Services.", "uz": "Octopos — restoran uchun yaxlit platforma: Guest (QR menyu va mustaqil buyurtma), POS (kassa va zalni boshqarish), Kitchen (oshxona ekrani), Order Display (buyurtma tayyorligi tablosi) va Dash (bek-ofis: tahlil, ombor, moliya va xodimlar). Biz Xizmatlarni yaxshilash uchun imkoniyatlarni qoʻshishimiz, oʻzgartirishimiz yoki toʻxtatishimiz mumkin.", "ru": "Octopos — комплексная платформа для ресторана: Guest (QR-меню и самостоятельные заказы), POS (касса и управление залом), Kitchen (кухонный экран), Order Display (табло готовности заказов) и Dash (бэк-офис: аналитика, склад, финансы и персонал). Мы можем добавлять, изменять или прекращать функции для улучшения Сервисов.", "ko": "Octopos는 올인원 레스토랑 플랫폼입니다: Guest(QR 메뉴·셀프 주문), POS(판매·플로어 관리), Kitchen(주방 디스플레이), Order Display(픽업 상태 표시), Dash(백오피스 분석·재고·재무·직원). 당사는 서비스 개선을 위해 기능을 추가·변경·중단할 수 있습니다.", "tr": "Octopos is an all-in-one restaurant platform: Guest (QR menu and self-ordering), POS (point of sale and floor management), Kitchen (kitchen display), Order Display (pickup status screen) and Dash (back-office analytics, inventory, finance and staff). We may add, change or discontinue features to improve the Services."},
  "legal.terms.s4t": {"en": "4. Accounts and access", "uz": "4. Hisoblar va kirish", "ru": "4. Учётные записи и доступ", "ko": "4. 계정 및 접근", "tr": "4. Accounts and access"},
  "legal.terms.s4b": {"en": "To use most Services you create an account for your venue. You are responsible for the accuracy of your registration details, for keeping your credentials secure, and for all activity under your account and staff logins. Notify us at support@octopos.uz if you suspect unauthorised access. You must be legally able to enter into these Terms and operate a business.", "uz": "Aksariyat Xizmatlardan foydalanish uchun muassasangiz uchun hisob yaratasiz. Roʻyxatdan oʻtish maʼlumotlarining toʻgʻriligi, hisob maʼlumotlaringiz xavfsizligi hamda hisobingiz va xodim loginlari ostidagi barcha harakatlar uchun siz javobgarsiz. Ruxsatsiz kirishga shubha qilsangiz, support@octopos.uz manziliga xabar bering. Siz ushbu Shartlarni tuzishga va biznes yuritishga qonuniy haqli boʻlishingiz kerak.", "ru": "Для использования большинства Сервисов вы создаёте учётную запись заведения. Вы отвечаете за достоверность регистрационных данных, сохранность учётных данных и за все действия в вашей учётной записи и под логинами сотрудников. Сообщите нам на support@octopos.uz при подозрении на несанкционированный доступ. Вы должны иметь право заключать настоящие Условия и вести бизнес.", "ko": "대부분의 서비스 이용을 위해 매장 계정을 생성합니다. 등록 정보의 정확성, 자격 증명의 보안, 계정 및 직원 로그인 하의 모든 활동에 대한 책임은 귀하에게 있습니다. 무단 접근이 의심되면 support@octopos.uz 로 알려주세요. 귀하는 본 약관을 체결하고 사업을 운영할 법적 자격이 있어야 합니다.", "tr": "To use most Services you create an account for your venue. You are responsible for the accuracy of your registration details, for keeping your credentials secure, and for all activity under your account and staff logins. Notify us at support@octopos.uz if you suspect unauthorised access. You must be legally able to enter into these Terms and operate a business."},
  "legal.terms.s5t": {"en": "5. Free trial, plans and billing", "uz": "5. Bepul davr, tariflar va toʻlov", "ru": "5. Бесплатный период, тарифы и оплата", "ko": "5. 무료 체험·요금제 및 결제", "tr": "5. Free trial, plans and billing"},
  "legal.terms.s5b": {"en": "New venues may start with a free first month. Paid plans renew monthly unless cancelled, and you can cancel with reasonable notice through your account or by contacting us. Fees are shown at checkout and may vary by plan, currency and location; hardware is invoiced separately. Prices may change with prior notice, taking effect from your next billing cycle.", "uz": "Yangi muassasalar birinchi oyni bepul boshlashi mumkin. Pulli tariflar bekor qilinmaguncha har oy uzaytiriladi; hisobingiz orqali yoki biz bilan bogʻlanib, oqilona muddatda bekor qilishingiz mumkin. Narxlar toʻlov paytida koʻrsatiladi va tarif, valyuta hamda hududga qarab farq qilishi mumkin; jihozlar alohida hisob-kitob qilinadi. Narxlar oldindan xabar berilgan holda oʻzgarishi va keyingi hisob-kitob davridan kuchga kirishi mumkin.", "ru": "Новые заведения могут начать с бесплатного первого месяца. Платные тарифы продлеваются ежемесячно, пока не отменены; отменить можно в разумный срок через учётную запись или обратившись к нам. Стоимость указывается при оформлении и может отличаться в зависимости от тарифа, валюты и региона; оборудование оплачивается отдельно. Цены могут меняться с предварительным уведомлением и вступают в силу со следующего расчётного периода.", "ko": "신규 매장은 첫 달을 무료로 시작할 수 있습니다. 유료 요금제는 해지 전까지 매월 갱신되며, 계정에서 또는 당사에 연락하여 합리적인 통지로 해지할 수 있습니다. 요금은 결제 시 표시되며 요금제·통화·지역에 따라 다를 수 있고, 하드웨어는 별도 청구됩니다. 가격은 사전 통지 후 변경될 수 있으며 다음 청구 주기부터 적용됩니다.", "tr": "New venues may start with a free first month. Paid plans renew monthly unless cancelled, and you can cancel with reasonable notice through your account or by contacting us. Fees are shown at checkout and may vary by plan, currency and location; hardware is invoiced separately. Prices may change with prior notice, taking effect from your next billing cycle."},
  "legal.terms.s6t": {"en": "6. Acceptable use", "uz": "6. Maqbul foydalanish", "ru": "6. Допустимое использование", "ko": "6. 허용되는 이용", "tr": "6. Acceptable use"},
  "legal.terms.s6b": {"en": "Use the Services to operate your venue lawfully. You must not: break any law; probe, disrupt or reverse-engineer the Services or their security; resell or provide access to third parties without our consent; upload malicious code; or send abusive, fraudulent or infringing content through our channels. We may limit or suspend use that puts the Services, other customers or third parties at risk.", "uz": "Xizmatlardan muassasangizni qonuniy yuritish uchun foydalaning. Quyidagilar taqiqlanadi: qonunni buzish; Xizmatlar yoki ularning xavfsizligini tekshirish, buzish yoki teskari muhandislik qilish; roziligimizsiz uchinchi shaxslarga qayta sotish yoki kirish berish; zararli kod yuklash; kanallarimiz orqali haqoratli, firibgar yoki huquqbuzar kontent yuborish. Xizmatlar, boshqa mijozlar yoki uchinchi shaxslar uchun xavf tugʻdiradigan foydalanishni cheklashimiz yoki toʻxtatishimiz mumkin.", "ru": "Используйте Сервисы для законной работы вашего заведения. Запрещено: нарушать закон; исследовать, нарушать или подвергать обратной разработке Сервисы либо их защиту; перепродавать или предоставлять доступ третьим лицам без нашего согласия; загружать вредоносный код; отправлять оскорбительный, мошеннический или нарушающий права контент через наши каналы. Мы можем ограничить или приостановить использование, создающее риск для Сервисов, других клиентов или третьих лиц.", "ko": "서비스를 매장 운영에 적법하게 사용하세요. 다음은 금지됩니다: 법률 위반; 서비스나 보안의 탐지·방해·역설계; 당사 동의 없는 재판매 또는 제3자 접근 제공; 악성 코드 업로드; 당사 채널을 통한 모욕적·사기적·침해적 콘텐츠 전송. 당사는 서비스, 다른 고객 또는 제3자에게 위험을 초래하는 이용을 제한하거나 중단할 수 있습니다.", "tr": "Use the Services to operate your venue lawfully. You must not: break any law; probe, disrupt or reverse-engineer the Services or their security; resell or provide access to third parties without our consent; upload malicious code; or send abusive, fraudulent or infringing content through our channels. We may limit or suspend use that puts the Services, other customers or third parties at risk."},
  "legal.terms.s7t": {"en": "7. Your content and data", "uz": "7. Kontentingiz va maʼlumotlaringiz", "ru": "7. Ваш контент и данные", "ko": "7. 귀하의 콘텐츠와 데이터", "tr": "7. Your content and data"},
  "legal.terms.s7b": {"en": "You retain ownership of the content you put into Octopos — menus, inventory, orders, sales data and guest information. You grant us the rights needed to host and process this content to provide the Services. We handle personal data as described in our Privacy Policy. You are responsible for having the right to use the content you upload and for complying with the laws that apply to your venue and guests.", "uz": "Octopos’ga joylaydigan kontent — menyu, ombor, buyurtmalar, savdo va mehmon maʼlumotlari — sizniki boʻlib qoladi. Ushbu kontentni Xizmatlarni taqdim etish uchun joylashtirish va qayta ishlashga zarur huquqlarni bizga berasiz. Shaxsiy maʼlumotlarni Maxfiylik siyosatimizga muvofiq qayta ishlaymiz. Yuklaydigan kontentga huquqingiz boʻlishi va muassasangiz hamda mehmonlaringizga oid qonunlarga rioya qilish siz zimmangizda.", "ru": "Вы сохраняете право собственности на контент, который размещаете в Octopos, — меню, склад, заказы, данные о продажах и гостях. Вы предоставляете нам права, необходимые для хостинга и обработки этого контента с целью предоставления Сервисов. Персональные данные мы обрабатываем согласно Политике конфиденциальности. Вы отвечаете за наличие прав на загружаемый контент и за соблюдение законов, применимых к вашему заведению и гостям.", "ko": "귀하가 Octopos에 입력하는 콘텐츠 — 메뉴, 재고, 주문, 매출 데이터, 게스트 정보 — 의 소유권은 귀하에게 있습니다. 귀하는 서비스 제공을 위해 이 콘텐츠를 호스팅·처리하는 데 필요한 권리를 당사에 부여합니다. 개인정보는 개인정보처리방침에 따라 처리합니다. 업로드 콘텐츠에 대한 권리 보유와 매장·게스트 관련 법 준수 책임은 귀하에게 있습니다.", "tr": "You retain ownership of the content you put into Octopos — menus, inventory, orders, sales data and guest information. You grant us the rights needed to host and process this content to provide the Services. We handle personal data as described in our Privacy Policy. You are responsible for having the right to use the content you upload and for complying with the laws that apply to your venue and guests."},
  "legal.terms.s8t": {"en": "8. Third-party integrations", "uz": "8. Uchinchi tomon integratsiyalari", "ru": "8. Сторонние интеграции", "ko": "8. 제3자 연동", "tr": "8. Third-party integrations"},
  "legal.terms.s8b": {"en": "The Services may connect to third-party tools you choose to enable (for example payments, delivery, messaging or accounting). Those tools are governed by their own terms, and we are not responsible for third-party services. When you enable an integration, you authorise the exchange of the data needed to make it work.", "uz": "Xizmatlar siz yoqadigan uchinchi tomon vositalariga (masalan, toʻlovlar, yetkazib berish, xabarlar yoki hisob) ulanishi mumkin. Bunday vositalar oʻz shartlari bilan tartibga solinadi va biz uchinchi tomon xizmatlari uchun javobgar emasmiz. Integratsiyani yoqqaningizda, uning ishlashi uchun zarur maʼlumot almashinuviga ruxsat berasiz.", "ru": "Сервисы могут подключаться к сторонним инструментам, которые вы выбираете (например, платежи, доставка, сообщения или учёт). Такие инструменты регулируются собственными условиями, и мы не несём ответственности за сторонние сервисы. Включая интеграцию, вы разрешаете обмен данными, необходимыми для её работы.", "ko": "서비스는 귀하가 활성화하는 제3자 도구(예: 결제, 배달, 메시징, 회계)에 연결될 수 있습니다. 해당 도구는 자체 약관의 적용을 받으며 당사는 제3자 서비스에 대해 책임지지 않습니다. 연동을 활성화하면 그 작동에 필요한 데이터 교환을 승인하는 것입니다.", "tr": "The Services may connect to third-party tools you choose to enable (for example payments, delivery, messaging or accounting). Those tools are governed by their own terms, and we are not responsible for third-party services. When you enable an integration, you authorise the exchange of the data needed to make it work."},
  "legal.terms.s9t": {"en": "9. Availability and support", "uz": "9. Mavjudlik va qoʻllab-quvvatlash", "ru": "9. Доступность и поддержка", "ko": "9. 가용성 및 지원", "tr": "9. Availability and support"},
  "legal.terms.s9b": {"en": "Octopos apps are offline-first and keep working through short network interruptions, syncing when the connection returns. We aim to keep the Services available but do not guarantee uninterrupted operation, and we may perform maintenance or updates. We provide support through the channels stated for your plan.", "uz": "Octopos ilovalari offline-first tarzda ishlaydi va qisqa tarmoq uzilishlarida ishlashda davom etib, ulanish tiklangach sinxronlashadi. Biz Xizmatlar mavjudligini taʼminlashga intilamiz, lekin uzluksiz ishlashni kafolatlamaymiz va texnik xizmat yoki yangilanishlar oʻtkazishimiz mumkin. Qoʻllab-quvvatlash tarifingiz uchun belgilangan kanallar orqali koʻrsatiladi.", "ru": "Приложения Octopos работают в режиме offline-first и продолжают работать при кратких перебоях сети, синхронизируясь после восстановления соединения. Мы стремимся поддерживать доступность Сервисов, но не гарантируем бесперебойную работу и можем проводить обслуживание или обновления. Поддержка предоставляется по каналам, указанным для вашего тарифа.", "ko": "Octopos 앱은 오프라인 우선으로 작동하여 짧은 네트워크 중단에도 계속 작동하고 연결 복구 시 동기화됩니다. 당사는 서비스 가용성을 유지하려 노력하나 무중단 작동을 보장하지 않으며 유지보수나 업데이트를 수행할 수 있습니다. 지원은 요금제에 명시된 채널을 통해 제공됩니다.", "tr": "Octopos apps are offline-first and keep working through short network interruptions, syncing when the connection returns. We aim to keep the Services available but do not guarantee uninterrupted operation, and we may perform maintenance or updates. We provide support through the channels stated for your plan."},
  "legal.terms.s10t": {"en": "10. Intellectual property", "uz": "10. Intellektual mulk", "ru": "10. Интеллектуальная собственность", "ko": "10. 지식재산권", "tr": "10. Intellectual property"},
  "legal.terms.s10b": {"en": "Octopos, its software, design, logos and content are owned by us or our licensors and are protected by law. These Terms do not transfer any of our intellectual property to you; we grant only a limited, non-exclusive, non-transferable right to use the Services while your account is active and in good standing.", "uz": "Octopos, uning dasturiy taʼminoti, dizayni, logotiplari va kontenti bizga yoki litsenziarlarimizga tegishli va qonun bilan himoyalangan. Ushbu Shartlar intellektual mulkimizni sizga oʻtkazmaydi; biz faqat hisobingiz faol va yaxshi holatda boʻlganda Xizmatlardan foydalanishning cheklangan, eksklyuziv boʻlmagan va boshqaga oʻtkazilmaydigan huquqini beramiz.", "ru": "Octopos, его программное обеспечение, дизайн, логотипы и контент принадлежат нам или нашим лицензиарам и защищены законом. Настоящие Условия не передают вам нашу интеллектуальную собственность; мы предоставляем лишь ограниченное, неисключительное и непередаваемое право использовать Сервисы, пока ваша учётная запись активна и в надлежащем состоянии.", "ko": "Octopos와 그 소프트웨어, 디자인, 로고, 콘텐츠는 당사 또는 라이선서의 소유이며 법으로 보호됩니다. 본 약관은 당사의 지식재산을 귀하에게 이전하지 않으며, 계정이 활성 상태이고 정상인 동안 서비스를 이용할 제한적·비독점적·양도 불가한 권리만 부여합니다.", "tr": "Octopos, its software, design, logos and content are owned by us or our licensors and are protected by law. These Terms do not transfer any of our intellectual property to you; we grant only a limited, non-exclusive, non-transferable right to use the Services while your account is active and in good standing."},
  "legal.terms.s11t": {"en": "11. Disclaimers and liability", "uz": "11. Kafolatlardan voz kechish va javobgarlik", "ru": "11. Отказ от гарантий и ответственность", "ko": "11. 보증 부인 및 책임 제한", "tr": "11. Disclaimers and liability"},
  "legal.terms.s11b": {"en": "To the maximum extent permitted by the law of the Republic of Uzbekistan, the Services are provided “as is” and “as available” without warranties of any kind. We are not liable for indirect, incidental or consequential losses, or for loss of profit or data, arising from your use of the Services. Nothing in these Terms limits liability that cannot be limited by law.", "uz": "Oʻzbekiston Respublikasi qonunchiligi ruxsat etgan eng yuqori darajada Xizmatlar «boricha» va «mavjud holicha», hech qanday kafolatsiz taqdim etiladi. Biz Xizmatlardan foydalanish natijasidagi bilvosita, tasodifiy yoki keyingi zararlar, shuningdek boy berilgan foyda yoki maʼlumot yoʻqolishi uchun javobgar emasmiz. Ushbu Shartlardagi hech narsa qonun boʻyicha cheklab boʻlmaydigan javobgarlikni cheklamaydi.", "ru": "В максимально допустимой законодательством Республики Узбекистан степени Сервисы предоставляются «как есть» и «как доступно», без каких-либо гарантий. Мы не отвечаем за косвенные, случайные или последующие убытки, а также за упущенную выгоду или потерю данных вследствие использования Сервисов. Ничто в настоящих Условиях не ограничивает ответственность, которую нельзя ограничить по закону.", "ko": "우즈베키스탄 공화국 법이 허용하는 최대 범위에서 서비스는 어떠한 보증도 없이 “있는 그대로” 및 “이용 가능한 대로” 제공됩니다. 당사는 서비스 이용으로 인한 간접·부수·결과적 손해, 이익 또는 데이터 손실에 책임지지 않습니다. 본 약관의 어떤 내용도 법으로 제한할 수 없는 책임을 제한하지 않습니다.", "tr": "To the maximum extent permitted by the law of the Republic of Uzbekistan, the Services are provided “as is” and “as available” without warranties of any kind. We are not liable for indirect, incidental or consequential losses, or for loss of profit or data, arising from your use of the Services. Nothing in these Terms limits liability that cannot be limited by law."},
  "legal.terms.s12t": {"en": "12. Suspension, termination and governing law", "uz": "12. Toʻxtatib turish, tugatish va amaldagi huquq", "ru": "12. Приостановление, прекращение и применимое право", "ko": "12. 중지·해지 및 준거법", "tr": "12. Suspension, termination and governing law"},
  "legal.terms.s12b": {"en": "You may stop using the Services at any time. We may suspend or terminate access if you breach these Terms or if required by law. On termination your right to use the Services ends; data handling after termination follows our Privacy Policy. These Terms are governed by the law of the Republic of Uzbekistan, and disputes are subject to the competent courts of Uzbekistan.", "uz": "Siz istalgan vaqtda Xizmatlardan foydalanishni toʻxtatishingiz mumkin. Shartlarni buzsangiz yoki qonun talab qilsa, biz kirishni toʻxtatib turishimiz yoki tugatishimiz mumkin. Tugatilganda Xizmatlardan foydalanish huquqingiz tugaydi; tugatishdan keyin maʼlumotlar bilan ishlash Maxfiylik siyosatimizga boʻysunadi. Ushbu Shartlar Oʻzbekiston Respublikasi qonunchiligiga boʻysunadi, nizolar esa Oʻzbekistonning vakolatli sudlarida koʻrib chiqiladi.", "ru": "Вы можете прекратить использование Сервисов в любое время. Мы можем приостановить или прекратить доступ при нарушении вами Условий или по требованию закона. При прекращении ваше право на использование Сервисов прекращается; обработка данных после прекращения регулируется Политикой конфиденциальности. Настоящие Условия регулируются законодательством Республики Узбекистан, а споры подлежат рассмотрению компетентными судами Узбекистана.", "ko": "귀하는 언제든 서비스 이용을 중단할 수 있습니다. 귀하가 약관을 위반하거나 법이 요구하는 경우 당사는 접근을 중지 또는 종료할 수 있습니다. 종료 시 서비스 이용 권리는 끝나며, 종료 후 데이터 처리는 개인정보처리방침을 따릅니다. 본 약관은 우즈베키스탄 공화국 법의 적용을 받으며 분쟁은 우즈베키스탄 관할 법원에 회부됩니다.", "tr": "You may stop using the Services at any time. We may suspend or terminate access if you breach these Terms or if required by law. On termination your right to use the Services ends; data handling after termination follows our Privacy Policy. These Terms are governed by the law of the Republic of Uzbekistan, and disputes are subject to the competent courts of Uzbekistan."},
  "legal.terms.s13t": {"en": "13. Changes and contact", "uz": "13. Oʻzgarishlar va aloqa", "ru": "13. Изменения и контакты", "ko": "13. 변경 및 문의", "tr": "13. Changes and contact"},
  "legal.terms.s13b": {"en": "We may update these Terms from time to time — for example to reflect changes in the law or the Services. We will give appropriate notice of material changes on the Sites or by email, and continued use after changes take effect means you accept them. Questions and requests are welcome at support@octopos.uz.", "uz": "Biz ushbu Shartlarni vaqti-vaqti bilan yangilashimiz mumkin — masalan, qonun yoki Xizmatlardagi oʻzgarishlarni aks ettirish uchun. Muhim oʻzgarishlar haqida Saytlarda yoki elektron pochta orqali tegishli tarzda xabar beramiz; oʻzgarishlar kuchga kirgandan keyin foydalanishda davom etsangiz, ularni qabul qilgan boʻlasiz. Savol va soʻrovlarni support@octopos.uz manziliga yuborishingiz mumkin.", "ru": "Мы можем периодически обновлять настоящие Условия — например, при изменении законодательства или Сервисов. О существенных изменениях мы уведомим надлежащим образом на Сайтах или по электронной почте; продолжение использования после вступления изменений в силу означает их принятие. Вопросы и запросы приветствуются на support@octopos.uz.", "ko": "당사는 법률 또는 서비스 변경 등을 반영하기 위해 본 약관을 수시로 업데이트할 수 있습니다. 중요한 변경은 사이트 또는 이메일로 적절히 통지하며, 변경 발효 후 계속 이용하면 이에 동의하는 것으로 간주됩니다. 질문과 요청은 support@octopos.uz 로 환영합니다.", "tr": "We may update these Terms from time to time — for example to reflect changes in the law or the Services. We will give appropriate notice of material changes on the Sites or by email, and continued use after changes take effect means you accept them. Questions and requests are welcome at support@octopos.uz."},
};
